const speed = Number(msg.payload.speed) || 0;
const speedMs = speed / 3.6;
const ax = Number(msg.payload.accelX) || 0;
const ay = Number(msg.payload.accelY) || 0;
const az = Number(msg.payload.accelZ) || 1.0;
const gx = Number(msg.payload.gyroX) || 0;
const gy = Number(msg.payload.gyroY) || 0;
const gz = Number(msg.payload.gyroZ) || 0;

// Força G horizontal total
const totalG = Math.sqrt(ax * ax + ay * ay).toFixed(2);

// Raio de Curva: R = v / omega
const omegaRad = Math.abs(gz) * (Math.PI / 180);
let radius = "--";
let turnType = "Straight Line";
let turnColor = "text-emerald-400";
let turnIcon = "fa-arrow-up";

if (speed < 2.0) {
    // Desativar raio de curva e manobras fantasmas com veículo parado
    turnType = "Stationary / Idle";
    turnColor = "text-slate-400";
    turnIcon = "fa-minus";
    radius = "--";
} else if (Math.abs(gz) < 3.5) {
    turnType = "Straight Line";
    turnColor = "text-emerald-400";
    turnIcon = "fa-arrow-up";
    radius = "> 500 m";
} else {
    const r = Math.round(speedMs / (omegaRad || 0.0001));
    radius = r + " m";
    // Regra da mão direita com eixo Z vertical para cima:
    // Rotação horária (curva à DIREITA) tem gz < 0.
    // Rotação anti-horária (curva à ESQUERDA) tem gz > 0.
    const dir = gz < 0 ? "Right" : "Left";
    turnIcon = gz < 0 ? "fa-arrow-right" : "fa-arrow-left";

    if (r < 35) {
        turnType = "Hairpin / Roundabout (" + dir + ")";
        turnColor = "text-rose-400";
    } else if (r < 110) {
        turnType = "Sharp " + dir + " Turn";
        turnColor = "text-amber-400";
    } else {
        turnType = "Mild " + dir + " Curve";
        turnColor = "text-cyan-400";
    }
}

// Detetor de eventos de condução
let event = speed < 2.0 ? "Stationary / Idle" : "Normal Cruise";
let eventBadge = speed < 2.0 ? "bg-slate-500/20 text-slate-300 border-slate-500/40" : "bg-emerald-500/20 text-emerald-300 border-emerald-500/40";
if (ay < -0.45 && speed > 5.0) {
    event = "Hard Braking!";
    eventBadge = "bg-rose-500/20 text-rose-300 border-rose-500/40 animate-pulse";
} else if (ay > 0.35 && speed > 3.0) {
    event = "Hard Acceleration";
    eventBadge = "bg-amber-500/20 text-amber-300 border-amber-500/40";
} else if (Math.abs(ax) > 0.45 && speed > 5.0) {
    event = "High Lateral G";
    eventBadge = "bg-purple-500/20 text-purple-300 border-purple-500/40";
} else if (Math.abs(az - 1.0) > 0.5 && speed > 10.0) {
    event = "Road Bump";
    eventBadge = "bg-orange-500/20 text-orange-300 border-orange-500/40";
}

msg.payload = {
    speed: speed,
    totalG: totalG,
    accelX: ax.toFixed(2),
    accelY: ay.toFixed(2),
    accelZ: az.toFixed(2),
    gyroX: gx.toFixed(1),
    gyroY: gy.toFixed(1),
    gyroZ: gz.toFixed(1),
    radius: radius,
    turnType: turnType,
    turnColor: turnColor,
    turnIcon: turnIcon,
    event: event,
    eventBadge: eventBadge,
    timestamp: msg.payload.timestamp || new Date().toISOString()
};
return msg;

const CRASH_G_THRESHOLD = 3.5; // G-force threshold
const COOLDOWN_MS = 60000;      // 60-second cooldown between alerts
const TELEGRAM_CHAT_ID = 0; // Replace with your Telegram Chat ID

// Context state to track cooldown
let lastAlertTime = context.get('lastAlertTime') || 0;
let now = Date.now();

let ax = Math.abs(Number(msg.payload.accelX) || 0);
let ay = Math.abs(Number(msg.payload.accelY) || 0);
let azRaw = Number(msg.payload.accelZ) || 1.0;
let az = Math.abs(azRaw);
let deltaAz = Math.abs(azRaw - 1.0);
let gx = Math.abs(Number(msg.payload.gyroX) || 0);
let gy = Math.abs(Number(msg.payload.gyroY) || 0);
let gz = Math.abs(Number(msg.payload.gyroZ) || 0);

let speed = Number(msg.payload.speed) || 0;
let latNum = Number(msg.payload.lat) || 0;
let lonNum = Number(msg.payload.lon) || 0;
let timestamp = msg.payload.timestamp || new Date().toISOString();

// Crash & Anomaly Classification
let isHorizontalImpact = (ax >= CRASH_G_THRESHOLD || ay >= CRASH_G_THRESHOLD);
let isVerticalImpact = (deltaAz >= CRASH_G_THRESHOLD || az >= CRASH_G_THRESHOLD);
// Capotamento só é acionado com rotação violenta (>120 deg/s) OU inversão (az < -0.2) com o veículo em movimento (>5 km/h)
let isRollover = (gx >= 120.0 || gy >= 120.0 || (azRaw < -0.2 && speed > 5.0));

let isCrash = (isHorizontalImpact || isVerticalImpact || isRollover);

if (isCrash && (now - lastAlertTime > COOLDOWN_MS)) {
    context.set('lastAlertTime', now);

    let peakG = Math.max(ax, ay, deltaAz).toFixed(2);
    let eventType = "Severe Impact / Collision";
    if (isRollover) {
        eventType = "Severe Vehicle Rollover / Inversion Detected";
    } else if (isVerticalImpact) {
        eventType = `Severe Vertical Impact / Drop (${deltaAz.toFixed(2)} G)`;
    } else if (isHorizontalImpact) {
        eventType = `Severe Collision Impact (${peakG} G)`;
    }

    let hasGpsFix = (latNum !== 0 && lonNum !== 0);
    let mapUrl = hasGpsFix ? `https://www.google.com/maps?q=${latNum.toFixed(6)},${lonNum.toFixed(6)}` : "Location Unavailable (No GPS Fix)";
    let locationStr = hasGpsFix ? `[Open in Google Maps](${mapUrl})` : "Coordinates Unavailable";

    // Retrieve active driver and email from session
    let driverName = flow.get('selectedDriver') || "Unknown Driver";
    let vehicleName = flow.get('selectedVehicle') || "Unknown Vehicle";
    let driverEmail = (flow.get('selectedDriverEmail') || "").trim();

    // Default emergency responders + dynamic driver email
    let recipients = ["alerts@example.com"];
    if (driverEmail && !recipients.includes(driverEmail)) {
        recipients.push(driverEmail);
    }

    // 1. Message formatted for Email Node (with dynamic 'to' list)
    let emailMsg = {
        to: recipients.join(', '),
        topic: `CRITICAL ALERT: ${eventType} - ${driverName} (${vehicleName})`,
        payload: `VEHICLE TELEMETRY EMERGENCY ALERT\n` +
                 `----------------------------------------\n` +
                 `Driver: ${driverName}\n` +
                 `Vehicle: ${vehicleName}\n` +
                 `Driver Email: ${driverEmail || 'N/A'}\n` +
                 `Event: ${eventType}\n` +
                 `Time: ${timestamp}\n` +
                 `Peak Force: ${peakG} G (X:${ax.toFixed(2)} Y:${ay.toFixed(2)} Z:${azRaw.toFixed(2)})\n` +
                 `Speed at Impact: ${speed} km/h\n` +
                 `Coordinates: ${hasGpsFix ? `${latNum.toFixed(6)}, ${lonNum.toFixed(6)}` : "No GPS Fix"}\n\n` +
                 `Live Google Maps Location:\n${mapUrl}\n` +
                 `----------------------------------------`,
        lat: latNum,
        lon: lonNum,
        peakG: peakG,
        eventType: eventType
    };

    // 2. Message formatted for Telegram Sender Node
    let telegramMsg = {
        payload: {
            chatId: TELEGRAM_CHAT_ID,
            type: "message",
            content: `*CRITICAL ALERT: ${eventType}!*\n` +
                     `----------------------------------------\n` +
                     `-> *Driver:* ${driverName} (${vehicleName})\n` +
                     `-> *Event:* ${eventType}\n` +
                     `-> *Peak Force:* ${peakG} G\n` +
                     `-> *Speed at Impact:* ${speed} km/h\n` +
                     `-> *Time:* ${timestamp}\n\n` +
                     `-> *Location:* ${locationStr}\n` +
                     `----------------------------------------`,
            options: {
                parse_mode: "Markdown"
            }
        }
    };

    return [emailMsg, telegramMsg];
}

return null;

// --- DYNAMIC DRIVING EFFICIENCY & VEHICLE CONTROL ENGINE ---
function computeScore(state) {
    const durationMin = (state.movingTimeSec || 0) / 60.0;
    let timeCap = 100.0 - 15.0 * Math.exp(-durationMin / 4.0);
    if (timeCap > 99.85) timeCap = 100.0;

    if (durationMin < 1.0) {
        return {
            score: 85.0,
            rawScore: 100.0,
            cap: Number(timeCap.toFixed(1)),
            movingMinutes: Number(durationMin.toFixed(2)),
            harshEvents: state.rawHarshEventsCount || 0,
            weightedHarshEvents: Number((state.weightedHarshEvents || 0).toFixed(1)),
            slipEvents: state.slipEventsCount || 0,
            peakG: Number((state.peakGripG || 0).toFixed(2)),
            status: "AGUARDANDO_TEMPO_MINIMO",
            breakdown: { pHarsh: 0, pPeak: 0, pChassis: 0, pSlip: 0, totalPenalty: 0 }
        };
    }

    const effectiveTime = Math.max(durationMin, 3.0);
    const timeRatio = 15.0 / effectiveTime;

    const pHarsh = 5.0 * ((state.weightedHarshEvents || 0) * timeRatio);
    const pPeak = 45.0 * Math.pow(Math.max(0.0, (state.peakGripG || 0) - 0.35), 2);
    const pChassis = 0.08 * Math.pow(Math.max(0.0, (state.maxChassisRate || 0) - 15.0), 2);
    const pSlip = 8.0 * ((state.slipEventsCount || 0) * timeRatio);

    const totalPenalty = pHarsh + pPeak + pChassis + pSlip;
    const rawScore = Math.max(0.0, Math.min(100.0, 100.0 * Math.exp(-0.020 * totalPenalty))); // True 0-100 scale
    const finalScore = Math.min(timeCap, rawScore);

    return {
        score: Number(finalScore.toFixed(1)),
        rawScore: Number(rawScore.toFixed(1)),
        cap: Number(timeCap.toFixed(1)),
        movingMinutes: Number(durationMin.toFixed(2)),
        harshEvents: state.rawHarshEventsCount || 0,
        weightedHarshEvents: Number((state.weightedHarshEvents || 0).toFixed(1)),
        slipEvents: state.slipEventsCount || 0,
        peakG: Number((state.peakGripG || 0).toFixed(2)),
        status: finalScore < rawScore ? "LIMITADO_POR_TEMPO" : "VALIDADO",
        breakdown: {
            pHarsh: Number(pHarsh.toFixed(1)),
            pPeak: Number(pPeak.toFixed(1)),
            pChassis: Number(pChassis.toFixed(1)),
            pSlip: Number(pSlip.toFixed(1)),
            totalPenalty: Number(totalPenalty.toFixed(1))
        }
    };
}

let p = String(msg.payload || "").toLowerCase();
let isStart = (p === "start_recording" || p === "start");
let isStop = (p === "stop_recording" || p === "stop");

// 1. START RECORDING
if (isStart) {
    let driver = flow.get('selectedDriver') || "";
    let vehicle = flow.get('selectedVehicle') || "";

    if (!driver || !vehicle) {
        let alertMsg = {
            payload: `
<div class="hud-banner hud-banner-alert">
    <div style="display: flex; align-items: center; gap: 10px;">
        <span class="hud-badge hud-badge-alert">[ALERT]</span>
        <span style="font-size: 12px; font-weight: 600; color: #fde68a;">PLEASE SELECT BOTH PILOT AND VEHICLE BEFORE RECORDING</span>
    </div>
    <div style="font-size: 11px; color: #d97706; font-weight: 600;">ACTION BLOCKED</div>
</div>`
        };
        return [null, alertMsg, null];
    }

    let now = new Date();
    let pad = (n) => String(n).padStart(2, '0');
    let tripId = `TRIP_${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;

    flow.set('isRecording', true);
    flow.set('currentTripId', tripId);
    flow.set('sessionStartTime', Date.now());
    flow.set('sessionTopSpeed', 0);
    flow.set('sessionPeakG', 0);
    flow.set('sessionPoints', 0);
    flow.set('sessionHarshEvents', 0);

    // Initialize Commercial-Grade Engine State with Dynamic Mass & Vehicle Specs (snapshot frozen at Start Recording)
    let rawPilotW = flow.get('pilotWeight');
    let initPilotWeight = (rawPilotW !== undefined && rawPilotW !== null && Number.isFinite(Number(rawPilotW)) && Number(rawPilotW) >= 0) ? Number(rawPilotW) : 75;
    let rawPassW = flow.get('passengerWeight');
    let initPassengerWeight = (rawPassW !== undefined && rawPassW !== null && Number.isFinite(Number(rawPassW)) && Number(rawPassW) >= 0) ? Number(rawPassW) : 0;
    let initPayload = initPilotWeight + initPassengerWeight;
    let initCurbWeight = Number(flow.get('vehicleWeight')) || 1635;
    let initTotalMass = initCurbWeight + initPayload;
    let initPowerHp = Number(flow.get('vehiclePower')) || 204;
    let initDrivetrain = flow.get('vehicleDrivetrain') || "FWD";

    flow.set('engineState', {
        movingTimeSec: 0.0,
        rawHarshEventsCount: 0,
        weightedHarshEvents: 0.0,
        slipEventsCount: 0,
        peakGripG: 0.0,
        maxChassisRate: 0.0,
        cooldownTimerSec: 0.0,
        lastTimestampMs: null,
        totalMassKg: initTotalMass,
        curbWeightKg: initCurbWeight,
        pilotWeightKg: initPilotWeight,
        passengerWeightKg: initPassengerWeight,
        payloadKg: initPayload,
        vehiclePowerHp: initPowerHp,
        drivetrain: initDrivetrain,
        peakWheelPowerHp: 0.0,
        totalBrakingWorkKj: 0.0
    });

    // Output 1: SQLite session insert
    let sqlMsg = {
        topic: `INSERT INTO sessions (id, driver, vehicle, start_time, curb_weight_kg, pilot_weight_kg, passenger_weight_kg, payload_kg, gross_mass_kg) VALUES ('${tripId}', '${driver.replace(/'/g, "''")}', '${vehicle.replace(/'/g, "''")}', datetime('now','localtime'), ${initCurbWeight}, ${initPilotWeight}, ${initPassengerWeight}, ${initPayload}, ${initTotalMass});`
    };

    // Output 2: Dynamic [REC] Banner for HUD
    let statusMsg = {
        payload: `
<div class="hud-banner hud-banner-rec">
    <div style="display: flex; align-items: center; gap: 10px;">
        <span class="hud-badge hud-badge-rec">[REC]</span>
        <span style="font-size: 12px; font-weight: 600; color: #fee2e2;">SESSION IN PROGRESS // TRIP: <strong style="color: #f87171;">${tripId}</strong></span>
    </div>
    <div style="font-size: 11px; color: #f87171; font-weight: 600;">${driver} &bull; ${vehicle}</div>
</div>`
    };

    return [sqlMsg, statusMsg, null];
}

// 2. STOP RECORDING
if (isStop) {
    if (!flow.get('isRecording')) {
        let alertMsg = {
            payload: `
<div class="hud-banner hud-banner-alert">
    <div style="display: flex; align-items: center; gap: 10px;">
        <span class="hud-badge hud-badge-alert">[STANDBY]</span>
        <span style="font-size: 12px; font-weight: 600; color: #fde68a;">NO ACTIVE SESSION TO STOP</span>
    </div>
    <div style="font-size: 11px; color: #d97706; font-weight: 600;">IDLE</div>
</div>`
        };
        return [null, alertMsg];
    }

    flow.set('isRecording', false);
    let tripId = flow.get('currentTripId') || "TRIP_UNKNOWN";
    let startMs = flow.get('sessionStartTime') || Date.now();
    let elapsedSec = Math.max(1, Math.round((Date.now() - startMs) / 1000));
    let mins = String(Math.floor(elapsedSec / 60)).padStart(2, '0');
    let secs = String(elapsedSec % 60).padStart(2, '0');
    let durationStr = `${mins}:${secs}`;

    let points = flow.get('sessionPoints') || 0;
    let topSpeed = flow.get('sessionTopSpeed') || 0;
    let driver = flow.get('selectedDriver') || "Pilot";
    let vehicle = flow.get('selectedVehicle') || "Vehicle";

    let state = flow.get('engineState') || {
        movingTimeSec: 0.0,
        rawHarshEventsCount: flow.get('sessionHarshEvents') || 0,
        weightedHarshEvents: flow.get('sessionHarshEvents') || 0,
        slipEventsCount: 0,
        peakGripG: flow.get('sessionPeakG') || 0,
        maxChassisRate: 0.0,
        cooldownTimerSec: 0.0,
        lastTimestampMs: null
    };

    let report = computeScore(state);
    let peakG = Math.max(state.peakGripG || 0, flow.get('sessionPeakG') || 0);
    let isInsufficient = points < 1500;
    let effDisplay = isInsufficient ? 'N/A' : `${Math.round(report.score)}%`;
    let effColor = isInsufficient ? '#94a3b8' : '#34d399';
    let statusText = isInsufficient ? 'DADOS INSUFICIENTES (< 1500 SAMPLES)' : report.status;
    let statusColor = isInsufficient ? '#94a3b8' : '#38bdf8';

    // Cache full debrief in context for reporting and PDF generation
    flow.set('lastSessionReport', {
        tripId: tripId,
        driver: driver,
        vehicle: vehicle,
        durationStr: durationStr,
        durationSec: elapsedSec,
        movingMinutes: report.movingMinutes,
        points: points,
        topSpeed: topSpeed,
        peakG: peakG,
        score: isInsufficient ? 'N/A' : report.score,
        rawScore: report.rawScore,
        cap: report.cap,
        status: statusText,
        isInsufficientData: isInsufficient,
        harshEvents: report.harshEvents,
        weightedHarshEvents: report.weightedHarshEvents,
        slipEvents: report.slipEvents,
        breakdown: report.breakdown
    });

    // Output 1: SQLite UPDATE session summary
    let sqlScoreVal = isInsufficient ? 'NULL' : Math.round(report.score);
    let sqlMsg = {
        topic: `UPDATE sessions SET end_time = datetime('now','localtime'), duration_sec = ${elapsedSec}, top_speed = ${topSpeed.toFixed(1)}, peak_g = ${peakG.toFixed(2)}, points_count = ${points}, efficiency_score = ${sqlScoreVal} WHERE id = '${tripId}';`
    };

    // Output 2: 5-Metric Debriefing HUD Card
    let debriefMsg = {
        payload: `
<div class="hud-debrief-card">
    <div class="hud-debrief-header">
        <div style="display: flex; align-items: center; gap: 8px;">
            <span class="hud-badge hud-badge-completed">[COMPLETED]</span>
            <span style="font-size: 12px; font-weight: 700; color: #f8fafc; letter-spacing: 0.3px;">SESSION DEBRIEF // ${tripId}</span>
        </div>
        <div style="font-size: 11px; color: #94a3b8; font-weight: 500;">${driver} &bull; ${vehicle} &bull; <span style="color: #fbbf24; font-weight: 700;">${state.totalMassKg || 1710} kg</span> &bull; <span style="color: ${statusColor}; font-weight: 600;">${statusText}</span></div>
    </div>
    <div class="hud-debrief-grid">
        <div class="hud-stat-box">
            <div class="hud-stat-label">DURATION</div>
            <div class="hud-stat-val" style="color: #f8fafc;">${durationStr}</div>
        </div>
        <div class="hud-stat-box">
            <div class="hud-stat-label">SAMPLES</div>
            <div class="hud-stat-val" style="color: #38bdf8;">${points}</div>
        </div>
        <div class="hud-stat-box">
            <div class="hud-stat-label">TOP SPEED</div>
            <div class="hud-stat-val" style="color: #fbbf24;">${topSpeed.toFixed(1)} <span style="font-size: 9px; color: #94a3b8;">km/h</span></div>
        </div>
        <div class="hud-stat-box">
            <div class="hud-stat-label">PEAK G</div>
            <div class="hud-stat-val" style="color: #f43f5e;">${peakG.toFixed(2)} <span style="font-size: 9px; color: #94a3b8;">G</span></div>
        </div>
        <div class="hud-stat-box">
            <div class="hud-stat-label">EFFICIENCY</div>
            <div class="hud-stat-val" style="color: ${effColor};">${effDisplay}</div>
        </div>
    </div>
</div>`
    };

    let driverEmail = flow.get('selectedDriverEmail') || '';
    let pdfTriggerMsg = {
        payload: tripId,
        tripId: tripId,
        driver: driver,
        driverEmail: driverEmail
    };
    return [sqlMsg, debriefMsg, pdfTriggerMsg];
}

// 3. INCOMING TELEMETRY SAMPLES
if (flow.get('isRecording') && msg.payload && typeof msg.payload.speed !== 'undefined') {
    let tripId = flow.get('currentTripId');
    let d = msg.payload;

    let speedKmh = Number(d.speed ?? 0);
    let engineTempC = Number(d.temp ?? 85);
    let yawRateDegS = Number(d.gyroZ ?? 0);
    let rollRateDegS = Number(d.gyroX ?? 0);
    let pitchRateDegS = Number(d.gyroY ?? 0);
    let latGX = Number(d.accelX ?? 0);
    let lonGY = Number(d.accelY ?? 0);
    let vertGZ = Number(d.accelZ ?? 1.0);

    let state = flow.get('engineState') || {
        movingTimeSec: 0.0,
        rawHarshEventsCount: 0,
        weightedHarshEvents: 0.0,
        slipEventsCount: 0,
        peakGripG: 0.0,
        maxChassisRate: 0.0,
        cooldownTimerSec: 0.0,
        lastTimestampMs: null
    };

    let nowMs = Date.now();
    let dtSec = 0.1;
    if (state.lastTimestampMs !== null) {
        dtSec = Math.min(1.0, Math.max(0.001, (nowMs - state.lastTimestampMs) / 1000.0));
    }
    state.lastTimestampMs = nowMs;

    // 1. Accumulate moving time only when vehicle is truly moving
    if (speedKmh > 3.0) {
        state.movingTimeSec += dtSec;
    }

    // Cooldown decrement
    if (state.cooldownTimerSec > 0) {
        state.cooldownTimerSec = Math.max(0.0, state.cooldownTimerSec - dtSec);
    }

    // 2. Anti-Pothole Filter (road noise rejection via Z-axis)
    let verticalDeltaG = Math.abs(vertGZ - 1.0);
    let currentChassisRate = Math.max(Math.abs(rollRateDegS), Math.abs(pitchRateDegS));
    let isRoadPotholeNoise = (verticalDeltaG > 0.65 && currentChassisRate < 12.0);

    // 3. Dynamic evaluation (skip peak/event penalties if road pothole noise)
    if (!isRoadPotholeNoise) {
        let currentGripG = Math.hypot(latGX, lonGY);
        if (currentGripG > state.peakGripG) {
            state.peakGripG = currentGripG;
        }
        if (currentChassisRate > state.maxChassisRate) {
            state.maxChassisRate = currentChassisRate;
        }

        // Mass & Power-Adaptive Dynamic Physics
        let massKg = state.totalMassKg || flow.get('totalMassKg') || 1710;
        let powerHp = state.vehiclePowerHp || flow.get('vehiclePower') || 204;
        let powerToWeight = powerHp / (massKg / 1000.0); // HP/Ton (e.g. 119.3 HP/Ton for Audi A3)

        // 1. Instantaneous mechanical wheel power under acceleration
        if (lonGY > 0.05 && speedKmh > 3.0) {
            let speedMs = speedKmh / 3.6;
            let forceNewtons = massKg * (lonGY * 9.81);
            let instantPowerHp = (forceNewtons * speedMs) / 745.7;
            state.peakWheelPowerHp = Math.max(state.peakWheelPowerHp || 0, instantPowerHp);
        }

        // 2. Cumulative braking thermal work estimation (kJ)
        if (lonGY < -0.20 && speedKmh > 5.0) {
            let speedMs = speedKmh / 3.6;
            let brakeForceN = massKg * (Math.abs(lonGY) * 9.81);
            let workKj = (brakeForceN * speedMs * dtSec) / 1000.0;
            state.totalBrakingWorkKj = (state.totalBrakingWorkKj || 0) + workKj;
        }

        // 3. Adaptive Harsh Driving Events (Kamm Ellipse + Thermal Multiplier + Inertia Load)
        if (state.cooldownTimerSec === 0.0 && speedKmh > 5.0) {
            // Acceleration limit scales with power-to-weight ratio (sports cars can accelerate harder)
            let accelLimit = Math.min(0.70, Math.max(0.32, 0.35 * (powerToWeight / 100.0)));
            // Braking limit scales slightly with load (heavier vehicle is more prone to brake lockup/fade)
            let brakeLimit = 0.45;
            let lonLimit = lonGY < 0 ? brakeLimit : accelLimit;

