    if (gpsVelMs < 0.3) {
        state.velMs = 0.0;
    } else {
        state.velMs = 0.85 * gpsVelMs + 0.15 * state.velMs;
    }

    // 5. Erro residual com amortecimento suave
    state.errLat = lat - state.estLat;
    state.errLon = lon - state.estLon;

    if (Math.abs(state.errLat) > 0.0003 || Math.abs(state.errLon) > 0.0003) {
        state.estLat = lat;
        state.estLon = lon;
        state.errLat = 0.0;
        state.errLon = 0.0;
    }
}

context.set("fusionState", state);

// 6. Timer 30 Hz (33 ms)
let timer = context.get("loop30Hz");
if (!timer) {
    timer = setInterval(function() {
        let st = context.get("fusionState");
        if (!st || !st.initialized || !st.baseMsg) return;
        if (Date.now() - st.lastPacketTime > 1500) return;

        // Se o veículo estiver parado, trava a velocidade e dissipa o erro sem translação (evita drift fantasma)
        if (st.velMs < 0.25) {
            st.velMs = 0.0;
            let stepErrLat = st.errLat * 0.15;
            let stepErrLon = st.errLon * 0.15;
            st.estLat += stepErrLat;
            st.estLon += stepErrLon;
            st.errLat -= stepErrLat;
            st.errLon -= stepErrLon;
        } else {
            // Em movimento: Dead Reckoning inercial
            let netAccelG = Math.max(-0.8, Math.min(0.8, st.accelForwardG - st.accelBiasG));
            let netAccelMs2 = netAccelG * G_TO_MS2;
            st.velMs = Math.max(0.0, st.velMs + netAccelMs2 * DT_30HZ);

            if (st.velMs > 0.8) {
                st.headingDeg = (st.headingDeg + st.gyroYawDegS * DT_30HZ + 360.0) % 360.0;
            }

            let headingRad = st.headingDeg * (Math.PI / 180.0);
            let dNorthMeters = st.velMs * Math.cos(headingRad) * DT_30HZ;
            let dEastMeters  = st.velMs * Math.sin(headingRad) * DT_30HZ;

            let dLat = dNorthMeters / 111320.0;
            let cosLat = Math.cos(st.estLat * (Math.PI / 180.0));
            let dLon = (cosLat > 0.0001) ? (dEastMeters / (111320.0 * cosLat)) : 0.0;

            let stepErrLat = st.errLat * 0.12;
            let stepErrLon = st.errLon * 0.12;

            st.estLat += dLat + stepErrLat;
            st.estLon += dLon + stepErrLon;
            st.errLat -= stepErrLat;
            st.errLon -= stepErrLon;
        }

        context.set("fusionState", st);

        if (!context.get("polygonCleared")) {
            node.send({ payload: { name: "Carro", deleted: true } });
            context.set("polygonCleared", true);
        }

        let outMsg = RED.util.cloneMessage(st.baseMsg);
        outMsg.payload.name = outMsg.payload.name || "Carro";
        outMsg.payload.icon = "car";
        outMsg.payload.iconColor = "#251f20b4";
        outMsg.payload.lat = Number(st.estLat.toFixed(7));
        outMsg.payload.lon = Number(st.estLon.toFixed(7));
        delete outMsg.payload.speed;
        outMsg.payload.speed_kmh = (st.velMs * 3.6).toFixed(1) + " km/h";
        outMsg.payload.bearing = Number(st.headingDeg.toFixed(1));

        node.send(outMsg);
    }, 33);

    context.set("loop30Hz", timer);
}

return null;

finalize:
let timer = context.get("loop30Hz");
if (timer) {
    clearInterval(timer);
    context.set("loop30Hz", null);
}
